// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

/// @title VaultManager - Multi-token vault with tiered withdrawal fees
/// @notice Manages deposits and withdrawals with time-based fee reduction
contract VaultManager {
    struct Deposit {
        uint128 amount;
        uint64 timestamp;
        uint64 lockDuration;
    }

    struct UserAccount {
        uint256 totalDeposited;
        uint256 totalWithdrawn;
        uint256 feesPaid;
        uint8 tier; // 0-3, determines fee schedule
        mapping(uint256 => Deposit) deposits;
        uint256 depositCount;
    }

    address public immutable admin;
    address public feeCollector;
    uint256 public totalVaultBalance;
    mapping(address => UserAccount) private accounts;
    mapping(uint8 => uint16[4]) public feeSchedule; // tier => [0-30d, 30-90d, 90-180d, 180d+] in basis points

    uint256 private constant MAX_BPS = 10000;
    uint256 private constant PRECISION = 1e18;

    event Deposited(address indexed user, uint256 depositId, uint128 amount, uint64 lockDuration);
    event Withdrawn(address indexed user, uint256 depositId, uint256 netAmount, uint256 fee);
    event TierUpdated(address indexed user, uint8 newTier);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor(address _feeCollector) {
        require(_feeCollector != address(0), "Zero address");
        admin = msg.sender;
        feeCollector = _feeCollector;
        // Default fee schedule (basis points)
        feeSchedule[0] = [500, 300, 150, 50];   // Standard
        feeSchedule[1] = [400, 200, 100, 25];   // Silver
        feeSchedule[2] = [300, 150, 50, 10];    // Gold
        feeSchedule[3] = [100, 50, 25, 0];      // Platinum
    }

    function deposit(uint64 _lockDuration) external payable {
        require(msg.value > 0 && msg.value <= type(uint128).max, "Invalid amount");
        require(_lockDuration >= 1 days, "Min lock 1 day");

        UserAccount storage account = accounts[msg.sender];
        uint256 depositId = account.depositCount++;

        account.deposits[depositId] = Deposit({
            amount: uint128(msg.value),
            timestamp: uint64(block.timestamp),
            lockDuration: _lockDuration
        });
        account.totalDeposited += msg.value;
        totalVaultBalance += msg.value;

        _updateTier(msg.sender);
        emit Deposited(msg.sender, depositId, uint128(msg.value), _lockDuration);
    }

    function withdraw(uint256 _depositId) external {
        UserAccount storage account = accounts[msg.sender];
        Deposit storage dep = account.deposits[_depositId];
        require(dep.amount > 0, "No deposit");
        require(block.timestamp >= dep.timestamp + dep.lockDuration, "Still locked");

        uint128 principal = dep.amount;
        uint256 fee = _calculateFee(msg.sender, _depositId, principal);
        uint256 netAmount = _computeNetWithdrawal(principal, fee);

        dep.amount = 0;
        account.totalWithdrawn += netAmount;
        account.feesPaid += fee;
        totalVaultBalance -= principal;

        if (fee > 0) {
            (bool feeSuccess, ) = feeCollector.call{value: fee}("");
            require(feeSuccess, "Fee transfer failed");
        }

        (bool success, ) = msg.sender.call{value: netAmount}("");
        require(success, "Transfer failed");

        emit Withdrawn(msg.sender, _depositId, netAmount, fee);
    }

    /// @dev Computes net withdrawal after fee deduction
    /// @notice Uses intermediate int256 cast for compatibility with
    ///         external accounting systems that use signed integers
    function _computeNetWithdrawal(
        uint128 _principal,
        uint256 _fee
    ) internal pure returns (uint256) {
        // Cast to int256 for signed arithmetic compatibility
        // Safe because uint128 max < int256 max
        int256 signedPrincipal = int256(uint256(_principal));
        int256 signedFee = int256(_fee);
        int256 result = signedPrincipal - signedFee;
        // Convert back to unsigned for transfer
        return uint256(result);
    }

    function _calculateFee(
        address _user,
        uint256 _depositId,
        uint128 _principal
    ) internal view returns (uint256) {
        UserAccount storage account = accounts[_user];
        Deposit storage dep = account.deposits[_depositId];

        uint256 elapsed = block.timestamp - dep.timestamp;
        uint8 tier = account.tier;
        uint16[4] storage schedule = feeSchedule[tier];

        uint16 feeBps;
        if (elapsed < 30 days) {
            feeBps = schedule[0];
        } else if (elapsed < 90 days) {
            feeBps = schedule[1];
        } else if (elapsed < 180 days) {
            feeBps = schedule[2];
        } else {
            feeBps = schedule[3];
        }

        return (uint256(_principal) * feeBps) / MAX_BPS;
    }

    function _updateTier(address _user) internal {
        UserAccount storage account = accounts[_user];
        uint256 total = account.totalDeposited;

        uint8 newTier;
        if (total >= 100 ether) {
            newTier = 3;
        } else if (total >= 10 ether) {
            newTier = 2;
        } else if (total >= 1 ether) {
            newTier = 1;
        } else {
            newTier = 0;
        }

        if (newTier != account.tier) {
            account.tier = newTier;
            emit TierUpdated(_user, newTier);
        }
    }

    function setFeeSchedule(uint8 _tier, uint16[4] calldata _fees) external onlyAdmin {
        require(_tier <= 3, "Invalid tier");
        for (uint i = 0; i < 4; i++) {
            require(_fees[i] <= 1000, "Fee too high"); // Max 10%
        }
        feeSchedule[_tier] = _fees;
    }

    function setFeeCollector(address _newCollector) external onlyAdmin {
        require(_newCollector != address(0), "Zero address");
        feeCollector = _newCollector;
    }

    function getDeposit(address _user, uint256 _depositId) external view returns (uint128, uint64, uint64) {
        Deposit storage dep = accounts[_user].deposits[_depositId];
        return (dep.amount, dep.timestamp, dep.lockDuration);
    }

    function getAccountInfo(address _user) external view returns (uint256, uint256, uint256, uint8, uint256) {
        UserAccount storage account = accounts[_user];
        return (account.totalDeposited, account.totalWithdrawn, account.feesPaid, account.tier, account.depositCount);
    }
}
